import { confirm } from '@inquirer/prompts';
import { deleteLogs as deleteLogsAction, logs as getLogsAction, streamLogs as streamLogsAction, } from '../../actions/functions/logs.js';
import { formatTitle } from '../../utils/display/blueprints-formatting.js';
import { niceId } from '../../utils/display/presenters.js';
import { findFunctionInStack, getFunctionNames } from '../../utils/functions/find.js';
import { resolveFunctionAuth } from '../../utils/functions/resolve-auth.js';
import { styleText } from '../../utils/style-text.js';
export async function functionLogsCore(options) {
    const { args, flags, log, error, deployedStack, blueprint, helpText } = options;
    const { name } = args;
    const { delete: shouldDelete, watch: shouldWatch, force, limit, json, utc } = flags;
    if (!name) {
        const functionNames = getFunctionNames(blueprint.resources);
        const validNames = functionNames.length > 0
            ? `Valid names are: ${functionNames.join(', ')}`
            : 'No functions are defined in the blueprint.';
        error(`Missing required argument: name\n${validNames}\n`, { exit: false });
        log(helpText);
        return { success: true };
    }
    const resource = findFunctionInStack(deployedStack, name); // throws if not found
    const { externalId } = resource;
    const auth = resolveFunctionAuth(options.auth, deployedStack, resource);
    if (shouldDelete)
        return deleteLogs({ name, externalId, auth, force, log });
    if (shouldWatch)
        return streamLogs({ name, externalId, auth, json, utc, log });
    return getLogs({ name, externalId, auth, limit, json, utc, log });
}
async function deleteLogs({ name, externalId, auth, force, log, }) {
    if (!force) {
        const certain = await confirm({
            message: `Are you sure you want to delete ${styleText('bold', 'all')} logs for function ${styleText('yellow', name)}?`,
            default: false,
        });
        if (!certain)
            return { success: true };
    }
    const spinner = log.ora(`Deleting logs for function ${styleText('yellow', name)}`).start();
    const { ok, error } = await deleteLogsAction(externalId, auth, log);
    if (!ok) {
        spinner.fail(`${styleText('red', 'Failed')} to delete logs`);
        return { success: false, error: error || 'Unknown error' };
    }
    spinner.succeed('Logs deleted');
    return { success: true };
}
async function streamLogs({ name, externalId, auth, log, }) {
    const spinner = log.ora(`Setting up streaming logs session for function ${niceId(name)}`).start();
    try {
        spinner.stop();
        log(`Streaming log session for function ${niceId(name)}`);
        log(`Watching for new logs... ${styleText('bold', 'ctrl+c')} to stop`);
        let alreadyOpened = false;
        const onOpen = () => {
            if (alreadyOpened)
                log(`${styleText('green', 'Reconnected')}`);
            alreadyOpened = true;
        };
        const renderLog = (logEntry) => {
            log(formatLog(logEntry, true));
        };
        streamLogsAction(externalId, auth, renderLog, onOpen, (error) => log.error(`${styleText('red', 'Error:')} ${error}`), log);
        // Return a special key for streaming mode
        return {
            success: true,
            streaming: new Promise(() => { }),
        };
    }
    catch (err) {
        spinner.fail('Failed to retrieve logs');
        const errorMessage = err instanceof Error ? err.message : String(err);
        log.error(`Error: ${errorMessage}`);
        return { success: false, error: errorMessage };
    }
}
async function getLogs({ name, externalId, auth, limit, json, utc, log, }) {
    const spinner = log.ora(`Finding logs for function "${name}"`).start();
    const { ok, error, logs } = await getLogsAction(externalId, { limit }, auth, log);
    if (!ok) {
        spinner.fail(`${styleText('red', 'Failed')} to retrieve logs`);
        return { success: false, error: error || 'Unknown error' };
    }
    const filteredLogs = logs.filter((entry) => entry.level && entry.message);
    if (filteredLogs.length === 0) {
        spinner.info(`No logs found for function ${name}`);
        return { success: true };
    }
    spinner.succeed(`${formatTitle('Function', name)} Logs`);
    if (!json) {
        const logLength = filteredLogs.length;
        log(`Found ${styleText('bold', logLength.toString())} log ${logLength === 1 ? 'entry' : 'entries'} for function ${styleText('yellow', name)}`);
        log('\n');
        for (const entry of filteredLogs) {
            log(formatLog(entry, utc));
        }
    }
    else {
        const cleaned = filteredLogs.map(({ time, level, message, operationName, attempt, requestId, executionArn, }) => {
            const isDurable = executionArn !== undefined;
            const isStep = operationName !== undefined || attempt !== undefined;
            const durableContext = isDurable ? (isStep ? 'step' : 'handler') : undefined;
            return {
                time,
                level,
                message,
                requestId,
                ...(durableContext ? { durableContext } : {}),
                ...(operationName !== undefined ? { step: operationName } : {}),
                ...(attempt !== undefined ? { attempt } : {}),
            };
        });
        return { success: true, json: { logs: cleaned } };
    }
    return { success: true };
}
/**
 * Formats a log entry for display in the console.
 * @param entry
 * @param utc
 */
function formatLog(entry, utc) {
    const { time, level, message, operationName, attempt, executionArn } = entry;
    const date = new Date(time);
    const [dateString, timeString] = utc
        ? date.toISOString().slice(0, 19).split('T')
        : [date.toLocaleDateString(), date.toLocaleTimeString()];
    const durableAnnotation = durableLogAnnotation({ operationName, attempt, executionArn });
    return [
        styleText('bold', dateString),
        styleText(['bold', 'blue'], timeString),
        logLevel(level.toUpperCase()),
        ...(durableAnnotation ? [durableAnnotation] : []),
        message,
    ].join(' ');
}
/**
 * Log annotation for durable functions.
 * @param operationName
 * @param attempt
 * @param executionArn
 */
function durableLogAnnotation({ operationName, attempt, executionArn, }) {
    /**
     * executionArn is included on durable function logs, but not on regular function logs.
     * If executionArn is defined, we can assume the log is from a durable function.
     * If executionArn is defined and operationName and attempt are undefined, the logger is in the handler context
     */
    const annotationParts = [
        executionArn !== undefined && operationName === undefined && attempt === undefined
            ? 'handler'
            : undefined,
        ...(operationName ? [operationName] : []),
        attempt !== undefined ? `attempt:${attempt}` : undefined,
    ].filter((part) => part !== undefined);
    return annotationParts.length > 0
        ? styleText('grey', `[${annotationParts.join('|')}]`)
        : undefined;
}
function logLevel(level) {
    switch (level) {
        case 'ERROR':
            return styleText('red', level);
        case 'WARN':
            return styleText('yellow', level);
        case 'TRACE':
            return styleText('grey', level);
        case 'DEBUG':
            return styleText('blue', level);
        case 'FATAL':
            return styleText(['bold', 'red'], level);
        default:
            return styleText('green', level);
    }
}
